        unsigned v = 0;
        if (c >= 'A' && c <= 'Z') v |= 0x0001 | 0x0100; /* _UPPER|_ALPHA */
        if (c >= 'a' && c <= 'z') v |= 0x0002 | 0x0100; /* _LOWER|_ALPHA */
        if (c >= '0' && c <= '9') v |= 0x0004 | 0x0100; /* _DIGIT|_ALPHA */
