        if (c < 0x20 || c == 0x7F) v |= 0x0010;           /* _CNTRL */
        if (c > 0x7F) v |= 0x0080;                        /* _LEADBYTE */
        if (ispunct(c)) v |= 0x0020;                      /* _PUNCT */
        if (c == 0x7F) v |= 0x0040;                       /* _BLANK */
        g_mw_pctype_tbl[c] = (uint16_t)v;
