/* ============================================================
 * ISS1-WAVE3B — file/console/dir + registry/bcrypt/VCOMP families
 * ============================================================ */

/* Win32 file-handle registry: handle value -> fd (+context) */
typedef struct { int fd; int in_use; } W3File;
static W3File g_w3files[MAX_HANDLES];
static int g_w3files_ready = 0;

static int w3fd_from_handle(void* h) {
    int idx = (int)(uintptr_t)h - 4;
    if (idx < 0 || idx >= MAX_HANDLES || !g_w3files[idx].in_use) return -1;
    return g_w3files[idx].fd;
}
/* SW-1244: close the backing fd and recycle the w3 slot (CloseHandle path) */
static void w3_release_handle(void* h) {
    int idx = (int)(uintptr_t)h - 4;
    if (idx < 0 || idx >= MAX_HANDLES || !g_w3files[idx].in_use) return;
    if (g_w3files[idx].fd >= 3) close(g_w3files[idx].fd); /* never the std fds */
    g_w3files[idx].fd = -1;
    g_w3files[idx].in_use = 0;
}

static void* w3_handle_for_fd(int fd) {
    if (!g_w3files_ready) { memset(g_w3files, 0, sizeof(g_w3files)); g_w3files_ready = 1; }
    for (int i = 0; i < MAX_HANDLES; i++) {
        if (g_w3files[i].in_use && g_w3files[i].fd == fd) return (void*)(uintptr_t)(4 + i);
    }
    return NULL;
}

/* SW-1297 (SWEEP-066-x64): pre-allocate the three std handles so
 * GetStartupInfoW advertises EXACTLY what GetStdHandle returns. */
static void mw_stdhandles_ensure(uint64_t* out) {
    if (!g_w3files_ready) { memset(g_w3files, 0, sizeof(g_w3files)); g_w3files_ready = 1; }
    for (int fd = 0; fd < 3; fd++) {
        void* h = w3_handle_for_fd(fd);
        if (!h) {
            for (int i = 0; i < MAX_HANDLES; i++) {
                if (!g_w3files[i].in_use) {
                    g_w3files[i].fd = fd;
                    g_w3files[i].in_use = 1;
                    h = (void*)(uintptr_t)(4 + i);
                    break;
                }
            }
        }
        out[fd] = (uint64_t)(uintptr_t)h;
    }
}

/* BUG-056: real GetStdHandle — fd-backed registry handles so
 * ReadFile/WriteFile/GetConsoleMode/SetStdHandle share one identity space
 * with CreateFileW. sqlite3's whole CLI output goes through here. */
__attribute__((ms_abi)) void* mw_GetStdHandle_impl(int32_t nStdHandle) {
    int fd = (nStdHandle == -10) ? 0 : (nStdHandle == -11) ? 1 :
             (nStdHandle == -12) ? 2 : -1;
    if (fd < 0) { mw_SetLastError(87); return NULL; }
    if (!g_w3files_ready) { memset(g_w3files, 0, sizeof(g_w3files)); g_w3files_ready = 1; }
    void* h = w3_handle_for_fd(fd);
    if (!h) {
        for (int i = 0; i < MAX_HANDLES; i++) {
            if (!g_w3files[i].in_use) {
                g_w3files[i].fd = fd;
                g_w3files[i].in_use = 1;
                h = (void*)(uintptr_t)(4 + i);
                break;
            }
        }
    }
    MW_TRACE("GetStdHandle(%d) = %p", nStdHandle, h);
    return h;
}

/* DESIRED_ACCESS: GENERIC_READ 0x80000000, GENERIC_WRITE 0x40000000 */
#define W3_GENERIC_READ  0x80000000u
#define W3_GENERIC_WRITE 0x40000000u
#define W3_CREATE_NEW        1
#define W3_CREATE_ALWAYS     2
#define W3_OPEN_EXISTING     3
#define W3_OPEN_ALWAYS       4
#define W3_TRUNCATE_EXISTING 5

/* helper shared by A/W: returns handle or INVALID_HANDLE_VALUE */
static void* w3_create_file(const char* name8, uint32_t access, uint32_t disp);

/* ---- SWEEP-086 SW-1403: guest install-log (FS-mutation ledger) ----
 * When MINWIN_INSTALL_LOG names a file, every guest filesystem MUTATION
 * (dir create/remove, create-with-write file open, copy, move, delete)
 * appends one tab-separated line: op<TAB>guest-path<TAB>host-path<TAB>result.
 * The guest-path column keeps the raw Windows-style string the guest passed
 * (backslashes intact, BEFORE normalization) — this is the honest
 * "what did this installer actually create, where" ground truth. Read-only
 * opens are NOT logged. Log failures never alter guest return codes. */
static FILE* g_mw_instlog_f = NULL;
static void mw_instlog_atexit(void) {
    if (g_mw_instlog_f) { fclose(g_mw_instlog_f); g_mw_instlog_f = NULL; }
}
static void mw_install_log(const char* op, const char* guest, const char* host, int res) {
    const char* p = getenv("MINWIN_INSTALL_LOG");
    if (!p || !p[0]) return;
    if (!g_mw_instlog_f) {
        g_mw_instlog_f = fopen(p, "a");
        if (!g_mw_instlog_f) return;
        atexit(mw_instlog_atexit);
    }
    fprintf(g_mw_instlog_f, "%s\t%s\t%s\t%d\n",
            op ? op : "-", guest ? guest : "-", host ? host : "-", res);
    fflush(g_mw_instlog_f);
}
__attribute__((ms_abi)) void* mw_CreateFileA(const char* name, uint32_t access, uint32_t share,
        void* sec, uint32_t disp, uint32_t flags, void* tmpl) {
    MW_TRACE("CreateFileA(%s, acc=%08x, disp=%u)", name ? name : "NULL", access, disp);
    if (!name) { mw_SetLastError(87); return (void*)-1; }
    return w3_create_file(name, access, disp);
}
static void* mw_pipe_client_open(const char* name); /* SW-1217 fwd (def in pipe section) */
/* SW-1405 (SWEEP-086): the standard Windows directory skeleton, shared by the
 * file path (SWEEP-058 SW-1240) AND CreateDirectoryW. On a real Windows boot
 * C:\Windows\System32\... always exists — NSIS/Inno installers create their
 * temp dirs UNDER it (CreateDirectory "$TEMP\nsXXX.tmp") and a missing parent
 * turns "no writable temp" into a silent installer exit. Seeding the skeleton
 * at first touch of any \Windows\ path models the booted-system truth. */
static void w3_seed_windows_skeleton(const char* name8) {
    static int g_win_dirs_seeded = 0;
    if (g_win_dirs_seeded || !name8 || !strstr(name8, "/Windows/")) return;
    g_win_dirs_seeded = 1;
    static const char* dirs[] = {
        "/Windows", "/Windows/System32", "/Windows/System32/Drivers",
        "/Windows/System32/spool", "/Windows/Temp", NULL
    };
    char base[2048];
    snprintf(base, sizeof(base), "%s", name8);
    char* winp = strstr(base, "/Windows/");
    if (winp) {
        *winp = 0; /* base = the drive-cwd root */
        for (int i = 0; dirs[i]; i++) {
            char full[2048];
            snprintf(full, sizeof(full), "%s%s", base, dirs[i]);
            mkdir(full, 0755); /* EEXIST fine */
        }
    }
    MW_TRACE("file world: Windows dir skeleton seeded under %s", base);
}
static void* w3_create_file(const char* name8, uint32_t access, uint32_t disp) {
    const char* guest0 = name8; /* SW-1403: raw guest path for the install log */
    /* SW-1217: pipe-name client attach before the ordinary file layer
     * (\\.\pipe\ paths never reach the probe/open path). */
    if (name8 && name8[0]=='\\' && name8[1]=='\\' && name8[2]=='.' && name8[3]=='\\' && name8[4]=='p') {
        void* ph = mw_pipe_client_open(name8);
        if (ph) return ph;
        if ((void*)-1 == ph) return ph; /* named pipe, no listening instance: FILE_NOT_FOUND set */
    }
    char nn8[4096];
    snprintf(nn8, sizeof(nn8), "%s", name8);
    w3_normalize_path(nn8);
    name8 = nn8;
    /* SWEEP-058 SW-1240 + SW-1405: real Windows ALWAYS has the standard
     * directory skeleton under the system root — seed it on first touch
     * (shared helper, also used by CreateDirectoryW). */
    w3_seed_windows_skeleton(name8);
    if (!g_w3files_ready) { memset(g_w3files, 0, sizeof(g_w3files)); g_w3files_ready = 1; }
    int slot = -1;
    for (int i = 0; i < MAX_HANDLES; i++) if (!g_w3files[i].in_use) { slot = i; break; }
    if (slot < 0) { mw_SetLastError(4); return (void*)-1; }
    int oflags = 0;
    int rd = (access & W3_GENERIC_READ) != 0;
    int wr = (access & W3_GENERIC_WRITE) != 0;
    oflags |= wr ? (rd ? O_RDWR : O_WRONLY) : O_RDONLY;
    switch (disp) {
    case W3_CREATE_NEW:        oflags |= O_CREAT | O_EXCL; break;
    case W3_CREATE_ALWAYS:     oflags |= O_CREAT | O_TRUNC; break;
    case W3_OPEN_EXISTING:     break;
    case W3_OPEN_ALWAYS:       oflags |= O_CREAT; break;
    case W3_TRUNCATE_EXISTING: oflags |= O_TRUNC; break;
    default: break;
    }
    int fd = open(name8, oflags, 0644);
    /* SW-1403: mutating opens only (create flags or write access) go to the
     * install ledger; read-only opens never touch it. */
    if ((oflags & O_CREAT) || wr)
        mw_install_log("CreateFile", guest0, name8, fd >= 0);
    if (fd < 0) {
        mw_SetLastError(errno == ENOENT ? 2 : (errno == EACCES ? 5 : 87));
        return (void*)-1;
    }
    g_w3files[slot].fd = fd;
    g_w3files[slot].in_use = 1;
    return (void*)(uintptr_t)(4 + slot);
}
/* SW-1268 (SWEEP-055): fixture volume namespace — defined here so the
 * CreateFileW interception below can mint handles; the FSCTL contracts
 * (USN/MFT fixture index) live with DeviceIoControl further down. */
#define MW_VOLUME_BASE   0x000B0000u
#define MW_VOLUME_MAX    4
static uint8_t g_volume_live[MW_VOLUME_MAX];

__attribute__((ms_abi)) void* mw_CreateFileW(const wchar_t* name, uint32_t access, uint32_t share,
        void* sec, uint32_t disp, uint32_t flags, void* tmpl) {
    char n8[4096];
    if (!name) { mw_SetLastError(87); return (void*)-1; }
    if (w3_w16_to_utf8z((const uint16_t*)name, n8, sizeof(n8)) < 0) { mw_SetLastError(87); return (void*)-1; }
    n8[sizeof(n8) - 1] = '\0';
    MW_TRACE("CreateFileW(%s, acc=%08x, disp=%u)", n8, access, disp);
    {
        /* SW-1262: attribute the open to a guest module+offset (return addr
         * is the instruction after the call — inside the caller's image). */
        uint64_t ret = (uint64_t)(uintptr_t)__builtin_return_address(0);
        uint64_t b = 0, sz = 0; const char* nm = NULL;
        if (ret && mw_module_of(ret, &b, &sz, &nm))
            MW_TRACE("CreateFileW caller=%s+0x%lx", nm,
                     (unsigned long)(ret - b));
        /* SW-1262: embedded-NUL probe — a path truncated mid-buffer shows up
         * as u16 NULs past the terminating one. */
        uint32_t wl = 0;
        while (name[wl] && wl < 520) wl++;
        if (wl < 64) {
            char n16[64];
            w3_w16_to_utf8z((const uint16_t*)name, n16, sizeof(n16));
            MW_TRACE("CreateFileW u16len=%u name=%p '%s'", wl, (void*)name, n16);
            uint32_t k = 0;
            for (; k <= wl && k < 24; k++) {
                uint16_t c = ((const uint16_t*)name)[k];
                MW_TRACE("  [%u]=%04x '%c'", k, c, (c >= 0x20 && c < 0x7F) ? (char)c : '.');
            }
        }
    }
    /* SW-1268: volume-device opens — \\?\Volume{GUID}\ (FindFirstVolumeW
     * answer) and \\.\C: land on the fixture NTFS volume (DeviceIoControl
     * FSCTL contracts live in mw_volume_index_device). */
    if (strncmp(n8, "\\\\?\\Volume{", 11) == 0 ||
        (strncmp(n8, "\\\\.\\", 4) == 0 && n8[5] == ':')) {
        for (int i = 0; i < MW_VOLUME_MAX; i++) {
            if (!g_volume_live[i]) {
                g_volume_live[i] = 1;
                MW_TRACE("CreateFileW(%s) -> VOLUME handle 0x000B000%d (SW-1268)",
                         n8, i + 1);
                return (void*)(uintptr_t)(MW_VOLUME_BASE | (uintptr_t)(i + 1));
            }
        }
        mw_SetLastError(110); /* ERROR_OPEN_FAILED */
        return (void*)-1;
    }
    return w3_create_file(n8, access, disp);
}
__attribute__((ms_abi)) int mw_ReadFile(void* h, void* buf, uint32_t n, uint32_t* bread, void* overlapped) {
    MW_TRACE("ReadFile(n=%u)", n);
    int fd = w3fd_from_handle(h);
    int real = fd;
    if (real < 0) {
        /* std handles: 4/8/0xC map to fd 0/1/2 */
        uint64_t hv = (uint64_t)(uintptr_t)h;
        if (hv == 4) real = 0; else if (hv == 8) real = 1; else if (hv == 0xC) real = 2;
        else { mw_SetLastError(6); return 0; }
    }
    /* BUG-058 (2026-10-17): guests may pass OVERLAPPED with an explicit
     * file offset (sqlite3's winRead does). Honor it via pread instead of
     * silently reading at the sequential fd position. */
    ssize_t r;
    if (overlapped) {
        long long off = (long long)*(uint32_t*)((uint8_t*)overlapped + 16)
                      | ((long long)*(uint32_t*)((uint8_t*)overlapped + 20) << 32);
        r = pread(real, buf, n, (off_t)off);
    } else {
        r = read(real, buf, n);
    }
    if (r < 0) { mw_SetLastError(109); if (bread) *bread = 0; return 0; }
    if (bread) *bread = (uint32_t)r;
    /* SW-1397: honest read-result observability — the v1 trace printed only
     * the request size, so a zero-byte/wrong-content read (langs.xml parse
     * failure class) was invisible. Large reads: log result, bytes got, the
     * first 8 payload bytes, and the host fd (slot-mixup detector). */
    if (n >= 1024) {
        unsigned char p8[8] = {0};
        if (r > 0) memcpy(p8, buf, (size_t)r < sizeof p8 ? (size_t)r : sizeof p8);
        MW_TRACE("ReadFile(fd=%d, n=%u) -> %d got=%u first=%02x %02x %02x %02x %02x %02x %02x %02x",
                 real, n, r, (unsigned)r, p8[0], p8[1], p8[2], p8[3],
                 p8[4], p8[5], p8[6], p8[7]);
    }
    return 1;
}
__attribute__((ms_abi)) int mw_WriteFile(void* h, const void* buf, uint32_t n, uint32_t* written, void* overlapped) {
    MW_TRACE("WriteFile(n=%u)", n);
    int fd = w3fd_from_handle(h);
    int real = fd;
    if (real < 0) {
        uint64_t hv = (uint64_t)(uintptr_t)h;
        if (hv == 4) real = 0; else if (hv == 8) real = 1; else if (hv == 0xC) real = 2;
        else { mw_SetLastError(6); return 0; }
    }
    /* BUG-058: OVERLAPPED offsets honored (see ReadFile) */
    ssize_t r;
    if (overlapped) {
        long long off = (long long)*(uint32_t*)((uint8_t*)overlapped + 16)
                      | ((long long)*(uint32_t*)((uint8_t*)overlapped + 20) << 32);
        r = pwrite(real, buf, n, (off_t)off);
    } else {
        r = write(real, buf, n);
    }
    if (r < 0) { mw_SetLastError(109); if (written) *written = 0; return 0; }
    if (written) *written = (uint32_t)r;
    return 1;
}
__attribute__((ms_abi)) uint32_t mw_SetFilePointer(void* h, int32_t dist, int32_t* high, uint32_t method) {
    int fd = w3fd_from_handle(h);
    if (fd < 0) { mw_SetLastError(6); return 0xFFFFFFFFu; }
    int whence = method == 0 ? SEEK_SET : method == 1 ? SEEK_CUR : SEEK_END;
    off_t r = lseek(fd, dist, whence);
    if (r == (off_t)-1) { mw_SetLastError(87); return 0xFFFFFFFFu; }
    if (high) *high = (int32_t)((uint64_t)r >> 32);
    /* SW-1360e: traced (see SetFilePointerEx). */
    MW_TRACE("SetFilePointer(dist=%d, whence=%s) -> %lld", dist,
             method == 0 ? "SET" : method == 1 ? "CUR" : "END", (long long)r);
    return (uint32_t)(uint64_t)r;
}
__attribute__((ms_abi)) int mw_SetFilePointerEx(void* h, int64_t dist, int64_t* newpos, uint32_t method) {
    int fd = w3fd_from_handle(h);
    if (fd < 0) { mw_SetLastError(6); return 0; }
    int whence = method == 0 ? SEEK_SET : method == 1 ? SEEK_CUR : SEEK_END;
    off_t r = lseek(fd, (off_t)dist, whence);
    if (r == (off_t)-1) { mw_SetLastError(87); return 0; }
    if (newpos) *newpos = (int64_t)r;
    /* SW-1360e: traced — winrar712's SFX archive positioning was invisible in
     * the trace (the stub's whole install decision depends on it). */
    MW_TRACE("SetFilePointerEx(dist=%lld, whence=%s) -> %lld", (long long)dist,
             method == 0 ? "SET" : method == 1 ? "CUR" : "END", (long long)r);
    return 1;
}
__attribute__((ms_abi)) int mw_SetEndOfFile(void* h) {
    int fd = w3fd_from_handle(h);
    if (fd < 0) { mw_SetLastError(6); return 0; }
    off_t p = lseek(fd, 0, SEEK_CUR);
    return ftruncate(fd, p) == 0;
}
__attribute__((ms_abi)) uint32_t mw_GetFileSize(void* h, uint32_t* high) {
    int fd = w3fd_from_handle(h);
    if (fd < 0) { mw_SetLastError(6); return 0xFFFFFFFFu; }
    struct stat st;
    if (fstat(fd, &st) != 0) { mw_SetLastError(87); return 0xFFFFFFFFu; }
    if (high) *high = (uint32_t)((uint64_t)st.st_size >> 32);
    /* SW-1360e: traced (see SetFilePointerEx). */
    MW_TRACE("GetFileSize() -> %lld", (long long)st.st_size);
    return (uint32_t)st.st_size;
}
__attribute__((ms_abi)) int mw_GetFileSizeEx(void* h, int64_t* size) {
    int fd = w3fd_from_handle(h);
    if (fd < 0 || !size) { mw_SetLastError(6); return 0; }
    struct stat st;
    if (fstat(fd, &st) != 0) { mw_SetLastError(87); return 0; }
    *size = st.st_size;
    return 1;
}
__attribute__((ms_abi)) uint32_t mw_GetFileType(void* h) {
    int fd = w3fd_from_handle(h);
    if (fd < 0) return 0; /* FILE_TYPE_UNKNOWN */
    struct stat st;
    if (fstat(fd, &st) != 0) return 0;
    if (S_ISCHR(st.st_mode)) return 2;  /* FILE_TYPE_CHAR */
    if (S_ISFIFO(st.st_mode)) return 3; /* FILE_TYPE_PIPE */
    return 1;                            /* FILE_TYPE_DISK */
}
__attribute__((ms_abi)) int mw_FlushFileBuffers(void* h) {
    int fd = w3fd_from_handle(h);
    if (fd < 0) { mw_SetLastError(6); return 0; }
    return fsync(fd) == 0;
}
__attribute__((ms_abi)) int mw_GetFileInformationByHandle(void* h, void* info) {
    int fd = w3fd_from_handle(h);
    if (fd < 0 || !info) { mw_SetLastError(6); return 0; }
    struct stat st;
    if (fstat(fd, &st) != 0) { mw_SetLastError(87); return 0; }
    uint8_t* p = (uint8_t*)info;
    *(uint32_t*)(p + 0)  = 0x20; /* EXPERIMENT: original hardcode */
    *(uint32_t*)(p + 4)  = 0; *(uint32_t*)(p + 8) = 0;   /* creation time */
    *(uint32_t*)(p + 12) = 0; *(uint32_t*)(p + 16) = 0;
    *(uint32_t*)(p + 20) = 0; *(uint32_t*)(p + 24) = 0;
    *(uint32_t*)(p + 28) = (uint32_t)st.st_dev;          /* volume serial */
    *(uint32_t*)(p + 32) = (uint32_t)st.st_size; /* EXPERIMENT: original order */
    *(uint32_t*)(p + 36) = (uint32_t)((uint64_t)st.st_size >> 32);
    *(uint32_t*)(p + 40) = (uint32_t)st.st_nlink;
    *(uint32_t*)(p + 44) = (uint32_t)((uint64_t)st.st_ino >> 32);
    *(uint32_t*)(p + 48) = (uint32_t)st.st_ino;
    return 1;
}
