/* ---- real .rsrc resource lookup (IMAGE_RESOURCE_DIRECTORY walk) ---- */
/* FindResourceA/W return an HRSRC = pointer to the IMAGE_RESOURCE_DATA_ENTRY;
 * LoadResource/LockResource resolve it to the data VA; SizeofResource reads
 * its Size field. */
static uint8_t* g_res_dir_base = NULL; /* section base of the last resource walk (SW-801d) */
/* SW-1277 (SWEEP-056): per-module resource resolution. The v1 walk hardcoded
 * g_image_base (the main EXE) for EVERY module: cards.dll!cdtInit does
 * LoadBitmapA(hinst_cards, 53/67/68) and sol.exe's RT_BITMAP dir has only 8
 * ids {3,4,5,6,9,14,16,24} while cards.dll ships 74 — the walk searched the
 * WRONG IMAGE, missed, and cdtInit fell into the 16x16 placeholder path, so
 * every metric came back 16x16 and sol's window computed to 152x64. Real
 * FindResource walks hmod's OWN PE header + .rsrc. Accept an hmod only when
 * it looks like a mapped PE (page-aligned + MZ + PE sig); anything else
 * (NULL, the exe base, synthetic handles) falls back to the main image. */
static uint64_t mw_main_image_base(void); /* SW-1475 fwd: active-world image base (def in the x86 section) */
static uint8_t* mw_res_pe_base(void* hmod) {
    /* SW-1475 (SWEEP-096): the default base must come from the ACTIVE world.
     * For PE32/cpu32 guests g_image_base stays NULL (the x64-native mmap
     * never ran) while the interpreted image is identity-mapped at
     * g_image_base32 — so the resource layer answered "no resources" for
     * EVERY PE32 guest: DialogBoxParamW resolved zero children (NPP
     * installer: GetDlgItem(1/2) -> NULL -> guest NULL-deref crash at
     * 0x406740 after 139.9M steps) and LoadStringW always returned 0. */
    uint8_t* pe = (uint8_t*)(uintptr_t)mw_main_image_base();
    if (hmod && ((uintptr_t)hmod & 0xFFFu) == 0 && *(const uint16_t*)hmod == 0x5A4D) {
        uint8_t* cand = (uint8_t*)hmod;
        uint32_t po = *(const uint32_t*)(cand + 0x3c);
        if (po && po < 0x1000000u && *(const uint32_t*)(cand + po) == 0x00004550u)
            pe = cand;
    }
    return pe;
}
static int w3_res_cmp_name(const uint8_t* dir_base, uint32_t name_off, const char* aname, const wchar_t* wname) {
    /* SWEEP-015 SW-801a: IS_INTRESOURCE — FindResource*(NULL, MAKEINTRESOURCE(5),
     * ...) passes numeric type/name as low pointers, never strings. */
    int a_num = (aname && (uintptr_t)aname > 0 && (uintptr_t)aname <= 0xFFFF) ? (int)(uintptr_t)aname : -1;
    int w_num = (wname && (uintptr_t)wname > 0 && (uintptr_t)wname <= 0xFFFF) ? (int)(uintptr_t)wname : -1;
    if (name_off & 0x80000000u) {
        /* string entry: numeric names never match a string entry */
        if (w_num >= 0 || a_num >= 0) return 1;
        /* string entry: WORD len, then UTF-16. SW-801b FIX: compare in real
         * 2-byte units — the old (wchar_t*) cast read the guest's UTF-16 as
         * 4-byte host wchars, which only worked for even-length names
         * (odd names like L"MAIN_WINDOW" misaligned the terminator check). */
        const uint8_t* s = dir_base + (name_off & 0x7FFFFFFFu);
        uint16_t len = *(const uint16_t*)s;
        const uint16_t* ws = (const uint16_t*)(s + 2);
        if (wname) {
            const uint16_t* wn = (const uint16_t*)wname;
            for (uint16_t i = 0; i < len; i++) {
                uint16_t c = ws[i], w = wn[i];
                uint16_t lc = (c >= 'A' && c <= 'Z') ? (uint16_t)(c + 32) : c;
                uint16_t lw = (w >= 'A' && w <= 'Z') ? (uint16_t)(w + 32) : w;
                if (lc != lw) return 1;
                if (!w) return 1;
            }
            return wn[len] ? 1 : 0;
        }
        if (!aname) return 1;
        for (uint16_t i = 0; i < len; i++) {
            uint16_t c = ws[i];
            char a = aname[i];
            int lc = (c >= 'A' && c <= 'Z') ? c + 32 : c;
            int la = (a >= 'A' && a <= 'Z') ? a + 32 : a;
            if (lc != la) return 1;
            if (!a) return 1;
        }
        return aname[len] ? 1 : 0;
    }
    /* ID entry */
    uint32_t id = name_off;
    if (w_num >= 0) return (w_num == (int)id) ? 0 : 1;
    if (a_num >= 0) return (a_num == (int)id) ? 0 : 1;
    long want = wname ? -1 : (aname ? atol(aname) : -1);
    if (wname) {
        wchar_t buf[16];
        int n = utf8_to_utf16("", buf, 0); (void)n;
        /* compare wname as decimal number */
        if (!wname[0]) return 1;
        long acc = 0;
        for (int i = 0; wname[i]; i++) {
            if (wname[i] < L'0' || wname[i] > L'9') return 1;
            acc = acc * 10 + (wname[i] - L'0');
            if (acc > 0x7FFFFFFFl) return 1;
        }
        return acc == id ? 0 : 1;
    }
    (void)want;
    if (!aname) return 1;
    /* numeric string or plain number */
    if (aname[0] == '#') {
        long acc = 0;
        for (const char* p = aname + 1; *p; p++) {
            if (*p < '0' || *p > '9') return 1;
            acc = acc * 10 + (*p - '0');
        }
        return acc == id ? 0 : 1;
    }
    return -1 == -1 ? 1 : 1; /* name string can't equal an ID entry */
}

static void* w3_res_find(void* hmod, const char* aname, const wchar_t* wname, const char* atype, const wchar_t* wtype) {
    if (!mw_main_image_base()) return NULL; /* SW-1475: active world (x64 native OR x86 interpreter) */
    MW_TRACE("[RES] find hmod=%p a=%s/%s w=%p/%p", hmod, atype ? atype : "?",
             aname ? (aname > (const char*)0xFFFF ? aname : "#num") : "-",
             (const void*)wname, (const void*)wtype);
    /* SW-1277: walk the CALLER's module (hmod), not always the main EXE */
    uint32_t rsrc_rva = 0;
    /* SW-1277: pe must stay in scope — base is THIS module's rsrc dir, not
     * the main exe's (the v2 half-fix kept base=g_image_base+rsrc_rva, which
     * added cards.dll's RVA 0x5000 onto the EXE base and walked sol's .text
     * as a resource directory: named=9332/ided=47168 garbage -> SIGSEGV). */
    uint8_t* pe = mw_res_pe_base(hmod);
    uint32_t pe_off = *(uint32_t*)(pe + 0x3c);
    /* SW-1301: the optional header differs PE32 vs PE32+ — NumberOfRvaAndSizes
     * sits at opt+92 (PE32) / opt+108 (PE32+), DataDirectory right after. The
     * old code hardcoded the PE32+ offsets, so PE32 guests read the Import
     * dir size as num_dd and the DEBUG dir as .rsrc — FindResource honestly
     * failed on every PE32 module (spider/sol are PE32+, masking it).
     * Branch on the magic. */
    uint16_t pe_magic = *(uint16_t*)(pe + pe_off + 24);
    uint32_t dd_off = (pe_magic == 0x20b) ? 108u : 92u; /* NumberOfRvaAndSizes */
    uint16_t num_dd = *(uint16_t*)(pe + pe_off + 24 + dd_off);
    if (num_dd < 3) return NULL;
    rsrc_rva = *(uint32_t*)(pe + pe_off + 24 + dd_off + 4 + 2 * 8); /* DataDirectory[2] */
    if (!rsrc_rva) return NULL;
    const uint8_t* base = pe + rsrc_rva;
    g_res_dir_base = (uint8_t*)base; /* SW-801d: LockResource/dialog data resolve */
    /* level 1: type, level 2: name, level 3: language */
    const uint8_t* level = base;
    for (int depth = 0; depth < 3; depth++) {
        /* SW-801c FIX: IMAGE_RESOURCE_DIRECTORY = {Characteristics(4),
         * TimeDateStamp(4), Major(2), Minor(2), NamedEntries(2)@12,
         * IdEntries(2)@14}. The old read at +8/+10 fetched the version
         * words (always 0) — the walk saw zero entries and EVERY
         * FindResource honestly failed. Offsets corrected to 12/14. */
        uint16_t named = *(const uint16_t*)(level + 12);
        uint16_t ided = *(const uint16_t*)(level + 14);
        uint16_t count = named + ided;
        const uint8_t* entries = level + 16;
        MW_TRACE("[RES] walk depth=%d level=%p named=%u ided=%u (base=%p)",
                 depth, (const void*)level, named, ided, (const void*)base);
        const uint8_t* next = NULL;
        for (uint16_t i = 0; i < count; i++) {
            uint32_t nm = *(const uint32_t*)(entries + i * 8);
            uint32_t of = *(const uint32_t*)(entries + i * 8 + 4);
            int match;
            /* SW-801c: level 3 is the LANGUAGE level — real FindResource
             * accepts any language; comparing the name again there made
             * every string-named resource unfindable. */
            if (depth == 0)      match = w3_res_cmp_name(base, nm, atype, wtype) == 0;
            else if (depth == 1) match = w3_res_cmp_name(base, nm, aname, wname) == 0;
            else                 match = 1;
            if (match) {
                if (of & 0x80000000u) {
                    next = base + (of & 0x7FFFFFFFu);
                    break;
                } else if (depth == 2) {
                    return (void*)(base + of); /* IMAGE_RESOURCE_DATA_ENTRY */
                }
                next = base + of;
                break;
            }
        }
        if (!next) {
            /* SW-1275 diag: name lookup failed at this depth — dump the dir
             * counters + entry names so a stateful break (header clobber,
             * dir corruption) is visible from the trace alone. */
            uint16_t f_named = *(const uint16_t*)(level + 12);
            uint16_t f_ided  = *(const uint16_t*)(level + 14);
            MW_TRACE("[RES] find miss depth=%d named=%u ided=%u base=%p rsrc_rva=%lu",
                     depth, f_named, f_ided, (void*)base, (unsigned long)rsrc_rva);
            for (uint16_t i = 0; i < f_named + f_ided && i < 64; i++) {
                uint32_t nm = *(const uint32_t*)(entries + i * 8);
                if (nm & 0x80000000u) {
                    const uint8_t* s = base + (nm & 0x7FFFFFFFu);
                    uint16_t ln = *(const uint16_t*)s;
                    char a[40] = { 0 };
                    for (uint16_t k = 0; k < ln && k < 19; k++) a[k] = (char)s[2 + 2 * k];
                    MW_TRACE("[RES]   entry[%u] str '%s'", i, a);
                } else {
                    MW_TRACE("[RES]   entry[%u] id %lu", i, (unsigned long)nm);
                }
            }
            return NULL;
        }
        level = next;
    }
    return NULL;
}
__attribute__((ms_abi)) void* mw_FindResourceA(void* hmod, const char* name, const char* type) {
    MW_TRACE("FindResourceA(type=%s, name=%s)", type ? type : "?", name ? name : "?");
    void* r = w3_res_find(hmod, name, NULL, type, NULL);
    if (!r) mw_SetLastError(1814); /* ERROR_RESOURCE_NAME_NOT_FOUND */
    return r;
}
