        g_tpw[i].live = 1; g_tpw[i].evt = NULL; g_tpw[i].pctx = pv;
        void* h = (void*)(uintptr_t)(MW_TPW_BASE | (unsigned)(i + 1));
        MW_TRACE("CreateThreadpoolWait -> %p", h);
