    if (!p || !size || mw_IsBadReadPtr(p, size)) return NULL;
    int n = (int)(size / 8u); /* SW-1317b: PE record stride 8 */
    if (n > MW_ACCEL_MAX) n = MW_ACCEL_MAX;
    int slot = -1;
