__attribute__((ms_abi)) int mw_GetMenuItemCount(void* menu) {
    int s = mw_menu_slot(menu);
    return s >= 0 ? (int)g_menus[s].count : -1;
}
__attribute__((ms_abi)) void* mw_GetSubMenu(void* menu, int pos) {
    int s = mw_menu_slot(menu);
    if (s < 0 || pos < 0 || (uint32_t)pos >= g_menus[s].count) return NULL;
    return g_menus[s].item[pos].sub;
}
/* MENUITEMINFO x64: cbSize@0 fMask@4 fType@8 fState@12 wID@16 hSubMenu@24
 * dwItemData@48 dwTypeData@56 cch@64 (sizeof 72). MIIM: STATE=1 ID=2
 * SUBMENU=4 STRING=0x40. */
__attribute__((ms_abi)) int mw_GetMenuItemInfoW(void* menu, uint32_t item, int bypos, void* mii) {
    int s = mw_menu_slot(menu);
    if (s < 0 || !mii) { mw_SetLastError(87); return 0; } /* ERROR_INVALID_PARAMETER */
    uint32_t* m = (uint32_t*)mii;
    if (m[0] < 72) { mw_SetLastError(87); return 0; }
    int i = bypos ? ((item < g_menus[s].count) ? (int)item : -1)
                  : mw_menu_find(s, item, 0);
    if (i < 0) { mw_SetLastError(87); return 0; }
    MwMenuItem* it = &g_menus[s].item[i];
    uint32_t mask = m[1];
    if (mask & 0x1u) m[3] = it->state;
    if (mask & 0x2u) m[4] = it->id;
    if (mask & 0x4u) *(void**)((uint8_t*)mii + 24) = it->sub;
    if (mask & 0x40u) {
        uint16_t** dst = (uint16_t**)((uint8_t*)mii + 56);
        uint32_t* cch = (uint32_t*)((uint8_t*)mii + 64);
        uint32_t n = 0;
        while (n + 1 < 32 && it->txt[n]) n++;
        if (*dst && *cch) mw_w16cpy(*dst, it->txt, (size_t)(*cch < n ? *cch : n) + 1);
        *cch = n;
    }
    MW_TRACE("GetMenuItemInfoW(menu=%p item=%lu) -> TRUE", menu, (unsigned long)item);
    return 1;
}
__attribute__((ms_abi)) int mw_GetMenuItemInfoA(void* menu, uint32_t item, int bypos, void* mii) {
    int s = mw_menu_slot(menu);
    if (s < 0 || !mii) { mw_SetLastError(87); return 0; }
    uint32_t* m = (uint32_t*)mii;
    if (m[0] < 72) { mw_SetLastError(87); return 0; }
    int i = bypos ? ((item < g_menus[s].count) ? (int)item : -1)
                  : mw_menu_find(s, item, 0);
    if (i < 0) { mw_SetLastError(87); return 0; }
    MwMenuItem* it = &g_menus[s].item[i];
    uint32_t mask = m[1];
    if (mask & 0x1u) m[3] = it->state;
    if (mask & 0x2u) m[4] = it->id;
    if (mask & 0x4u) *(void**)((uint8_t*)mii + 24) = it->sub;
    if (mask & 0x40u) {
        char** dst = (char**)((uint8_t*)mii + 56);
        uint32_t* cch = (uint32_t*)((uint8_t*)mii + 64);
        uint32_t n = 0;
        while (n + 1 < 32 && it->txt[n]) n++;
        if (*dst && *cch) {
            uint32_t k = 0;
            for (; k < n && k + 1 < (uint32_t)*cch; k++) (*dst)[k] = (char)(it->txt[k] & 0xFF);
            (*dst)[k] = 0;
        }
        *cch = n;
    }
    MW_TRACE("GetMenuItemInfoA(menu=%p item=%lu) -> TRUE", menu, (unsigned long)item);
    return 1;
}

/* ---- SWEEP-021 SW-881..885: menu deepening (completes the item model) ---- */
static int mw_menu_insert_at(int s, int pos, const MwMenuItem* src) {
    if (g_menus[s].count >= MW_MENU_NITEM) return 0;
    if (pos < 0 || (uint32_t)pos > g_menus[s].count) pos = (int)g_menus[s].count;
    for (int i = (int)g_menus[s].count; i > pos; i--)
        g_menus[s].item[i] = g_menus[s].item[i - 1];
    g_menus[s].item[pos] = *src;
    g_menus[s].count++;
    return 1;
}
__attribute__((ms_abi)) int mw_InsertMenuItemW(void* menu, uint32_t item, int bypos, const void* mii) {
    int s = mw_menu_slot(menu);
    if (s < 0 || !mii) { mw_SetLastError(87); return 0; }
    if (*(const uint32_t*)mii < 72) { mw_SetLastError(87); return 0; }
    const uint32_t* m = (const uint32_t*)mii;
    MwMenuItem it; memset(&it, 0, sizeof(it));
    uint32_t mask = m[1];
    if (mask & 0x2u) it.id = m[4];
    if (mask & 0x1u) it.state = (uint16_t)(m[3] & (8u | 1u | 2u));
    if (mask & 0x4u) it.sub = *(void* const*)((const uint8_t*)mii + 24);
    if (mask & 0x40u) {
        const uint16_t* const* pw = (const uint16_t* const*)((const uint8_t*)mii + 56);
        uint16_t tmp[32];
        if (pw && *pw && mw_probe_copy(*pw, 62, tmp)) mw_w16cpy(it.txt, tmp, 32);
    }
    int pos = bypos ? (int)item : (int)g_menus[s].count; /* BYCOMMAND -> append */
    if (!mw_menu_insert_at(s, pos, &it)) return 0;
    MW_TRACE("InsertMenuItemW(menu=%p pos=%d) count->%u", menu, pos, g_menus[s].count);
    return 1;
}
__attribute__((ms_abi)) int mw_InsertMenuItemA(void* menu, uint32_t item, int bypos, const void* mii) {
    int s = mw_menu_slot(menu);
    if (s < 0 || !mii) { mw_SetLastError(87); return 0; }
    if (*(const uint32_t*)mii < 72) { mw_SetLastError(87); return 0; }
    const uint32_t* m = (const uint32_t*)mii;
    MwMenuItem it; memset(&it, 0, sizeof(it));
    uint32_t mask = m[1];
    if (mask & 0x2u) it.id = m[4];
    if (mask & 0x1u) it.state = (uint16_t)(m[3] & (8u | 1u | 2u));
    if (mask & 0x4u) it.sub = *(void* const*)((const uint8_t*)mii + 24);
    if (mask & 0x40u) {
        const char* const* pa = (const char* const*)((const uint8_t*)mii + 56);
        char a[32];
        if (pa && *pa && mw_probe_copy(*pa, 31, a))
            for (int j = 0; j < 31 && a[j]; j++) it.txt[j] = (uint16_t)(uint8_t)a[j];
    }
    int pos = bypos ? (int)item : (int)g_menus[s].count;
    if (!mw_menu_insert_at(s, pos, &it)) return 0;
    MW_TRACE("InsertMenuItemA(menu=%p pos=%d) count->%u", menu, pos, g_menus[s].count);
    return 1;
}
__attribute__((ms_abi)) int mw_RemoveMenu(void* menu, uint32_t item, uint32_t flags) {
    int s = mw_menu_slot(menu);
    if (s < 0) return 0;
    int i = mw_menu_find(s, item, flags);
    if (i < 0) return 0;
    /* RemoveMenu keeps the popped submenu alive (Windows semantics) */
    for (int j = i; j < (int)g_menus[s].count - 1; j++)
        g_menus[s].item[j] = g_menus[s].item[j + 1];
    g_menus[s].count--;
    memset(&g_menus[s].item[g_menus[s].count], 0, sizeof(MwMenuItem));
    MW_TRACE("RemoveMenu(menu=%p item=%lu) -> TRUE count->%u", menu,
             (unsigned long)item, g_menus[s].count);
    return 1;
}
__attribute__((ms_abi)) int mw_DeleteMenu(void* menu, uint32_t item, uint32_t flags) {
    int s = mw_menu_slot(menu);
    if (s < 0) return 0;
    int i = mw_menu_find(s, item, flags);
    if (i < 0) return 0;
    void* sub = g_menus[s].item[i].sub;
    for (int j = i; j < (int)g_menus[s].count - 1; j++)
        g_menus[s].item[j] = g_menus[s].item[j + 1];
    g_menus[s].count--;
    memset(&g_menus[s].item[g_menus[s].count], 0, sizeof(MwMenuItem));
    if (sub) mw_DestroyMenu(sub); /* DeleteMenu destroys the popped submenu */
    MW_TRACE("DeleteMenu(menu=%p item=%lu) -> TRUE count->%u", menu,
             (unsigned long)item, g_menus[s].count);
    return 1;
}
__attribute__((ms_abi)) int mw_GetMenuItemRect(void* hwnd, void* menu, uint32_t index, void* lprc) {
    (void)hwnd;
    int s = mw_menu_slot(menu);
    if (s < 0 || !lprc || index >= g_menus[s].count) { mw_SetLastError(87); return 0; }
    /* honest synthetic layout: bar rows 18px tall, 120px wide */
    int32_t* r = (int32_t*)lprc;
    r[0] = 0; r[1] = (int32_t)index * 18; r[2] = 120; r[3] = r[1] + 18;
    MW_TRACE("GetMenuItemRect(menu=%p index=%lu) -> TRUE", menu, (unsigned long)index);
    return 1;
}
__attribute__((ms_abi)) int mw_TrackPopupMenuEx(void* menu, uint32_t flags, int x, int y,
        void* hwnd, const void* tpm) {
    (void)flags; (void)x; (void)y; (void)hwnd; (void)tpm;
    /* headless: menu shows and is dismissed with nothing chosen — the honest
     * no-user contract; 0 with no error set */
    mw_SetLastError(0);
    MW_TRACE("TrackPopupMenuEx(menu=%p) -> 0 (no user, dismissed)", menu);
    return 0;
}

/* ---- user32: misc window APIs ---- */
static uint8_t g_winplace[44]; /* WINDOWPLACEMENT, x64 sizeof == 44 (SWEEP-014) */
static uint8_t g_winplace_live = 0;
__attribute__((ms_abi)) int mw_GetWindowPlacement(void* hwnd, void* wp) {
    (void)hwnd;
    if (!wp) return 0;
    /* SWEEP-014: SetWindowPlacement (below) stores the guest's placement —
     * honest round-trip when placed; documented defaults otherwise. */
    if (g_winplace_live) {
        memcpy(wp, g_winplace, 44);
        MW_TRACE("GetWindowPlacement -> TRUE (stored placement)");
        return 1;
    }
    uint8_t* p = (uint8_t*)wp;
    /* WINDOWPLACEMENT x64: length@0 flags@4 showCmd@8 ptMin@12 ptMax@20
     * rcNormal@28..44 rcPad? -> writer-safe: only fill beyond length field */
    *(uint32_t*)(p + 4) = 0;             /* flags */
    *(uint32_t*)(p + 8) = 1;             /* showCmd = SW_SHOWNORMAL */
    *(int32_t*)(p + 12) = 0; *(int32_t*)(p + 16) = 0;
    *(int32_t*)(p + 20) = 0; *(int32_t*)(p + 24) = 0;
    *(int32_t*)(p + 28) = 0;  *(int32_t*)(p + 32) = 0;
    *(int32_t*)(p + 36) = g_win_w; *(int32_t*)(p + 40) = g_win_h;
    MW_TRACE("GetWindowPlacement -> showCmd=1 normal %dx%d", g_win_w, g_win_h);
    return 1;
}
__attribute__((ms_abi)) int mw_GetWindowRect(void* hwnd, void* rc) {
    if (!rc) return 0;
    int32_t* r = (int32_t*)rc;
    /* SW-1327 (sweep075): a CHILD window answers with its OWN rect (the
     * mw_child_set_rect record, parent-client-relative like real Windows).
     * The old code returned the MAIN surface rect for every handle, so the
     * puzzles' get_statusbar_height() read the MAIN height (427) as the
     * statusbar height -> adjust_statusbar resized the main window to
     * 11x427 -> new_bitmap(11x11) -> the board painted into 32x32. Same
     * contract family as SW-1288 (children own their rect records). */
    int slot = mw_child_slot(hwnd);
    if (slot >= 0 && g_child[slot].live) {
        r[0] = g_child[slot].rx; r[1] = g_child[slot].ry;
        r[2] = g_child[slot].rx + g_child[slot].rw;
        r[3] = g_child[slot].ry + g_child[slot].rh;
        MW_TRACE("GetWindowRect(child slot %d) -> %dx%d@%d,%d", slot,
                 g_child[slot].rw, g_child[slot].rh,
                 g_child[slot].rx, g_child[slot].ry);
        return 1;
    }
    r[0] = 0; r[1] = 0; r[2] = g_win_w; r[3] = g_win_h;
    MW_TRACE("GetWindowRect -> %dx%d", g_win_w, g_win_h);
    return 1;
}
__attribute__((ms_abi)) int mw_MoveWindow(void* hwnd, int x, int y, int w, int h, int repaint) {
    /* SW-1266b: grow the surface to the requested client size (see
     * SetWindowPos note — winmine's post-create board sizing).
     * SW-1288 (SWEEP-061): ONLY the MAIN window may resize the paint
     * surface. A child's MoveWindow (sol's statusbar MoveWindow(587,10)
     * during its own WM_SIZE layout) used to shrink the MAIN surface to
     * 587x32 — the board then painted into a 32px client and the final
     * frame was blank. Children resize only their own child-rect record. */
    if (w > 0 && h > 0) {
        /* SW-1288: child iff the handle carries the child-hwnd marker */
        int is_main = (mw_child_slot(hwnd) < 0); /* SW-1288 FIX: slot() returns -1 for non-children — !(-1)==0 misrouted MAIN windows to the child path */
        if (is_main) {
            mw_gui_store_window(w, h);
            mw_gui_send_size_sync(g_win_w, g_win_h, "SW-1287c MoveWindow"); /* SW-1287c */
        }
        else mw_child_set_rect(hwnd, x, y, w, h);
    }
    MW_TRACE("MoveWindow(hwnd=%p main=%d, %dx%d@%d,%d) -> TRUE", hwnd,
             (int)(mw_child_slot(hwnd) < 0), w, h, x, y);
    return 1;
}
