/* oleaut32!VariantInit (ordinal 8): the documented contract — vt = VT_EMPTY,
 * the rest zeroed. VARIANT is 24 bytes on x64. */
__attribute__((ms_abi)) void mw_VariantInit(void* pvarg) {
    if (pvarg) memset(pvarg, 0, 24);
    MW_TRACE("VariantInit -> VT_EMPTY");
}

/* gdi32!CreateDIBSection — REAL raster allocation (WinMergeU bitmap paths,
 * and every GUI guest that needs CPU-accessible DIB bits). We parse the
 * BITMAPINFOHEADER honestly, allocate from the same MWBmp pool as
 * CreateCompatibleBitmap (3 bytes/px BGR, matching the engine raster), and
 * hand the guest a real pointer to the pixels. SWEEP-028: the pool stores the
 * GUEST-requested view format (vbpp/vtop/vstride on MWBmp) — 16/24/32bpp and
 * top-down all honest; engine reads/writes go through mwb_get/mwb_set. */
__attribute__((ms_abi)) void* mw_CreateDIBSection(void* hdc, const void* pbmi,
        uint32_t usage, void** ppvBits, void* hSection, uint32_t offset) {
    (void)hdc; (void)usage; (void)hSection; (void)offset;
    if (!pbmi || !ppvBits) return NULL;
    const uint8_t* bmi = (const uint8_t*)pbmi;
    int32_t w  = *(const int32_t*)(bmi + 4);
    int32_t h  = *(const int32_t*)(bmi + 8);
    uint16_t bpp = *(const uint16_t*)(bmi + 14);
    uint32_t comp = *(const uint32_t*)(bmi + 16);
    if (w <= 0 || h == 0) {
        MW_TRACE("CreateDIBSection -> NULL (bad dims %dx%d)", w, h);
        return NULL;
    }
    if (comp != 0 /*BI_RGB*/ && comp != 3 /*BI_BITFIELDS*/) {
        MW_TRACE("CreateDIBSection -> NULL (compression %u unsupported)", comp);
        return NULL;
    }
    if (bpp != 16 && bpp != 24 && bpp != 32) {
        MW_TRACE("CreateDIBSection -> NULL (%u bpp unsupported)", bpp);
        return NULL;
    }
    /* SWEEP-028 (SW-1101 root cause): h<0 = TOP-DOWN DIB. Old code computed
     * (size_t)w*(size_t)h -> underflow -> calloc failed -> NULL with NO trace;
     * WinMerge's 32bpp top-down toolbar DIB then hit SelectObject(NULL) and
     * its RGBA loop wrote at NULL+0x154 (SIGSEGV RVA 0x12d0c2). */
    int32_t abs_h = (h > 0) ? h : -h;
    uint32_t vstride = ((uint32_t)w * (uint32_t)bpp + 31u) / 32u * 4u;
    for (int i = 0; i < MW_MEMDC_MAX; i++) {
        if (!g_bitmap_live[i]) {
            g_bitmap_live[i] = 1;
            g_bitmap_obj[i].w = w; g_bitmap_obj[i].h = abs_h;
            g_bitmap_obj[i].vbpp = bpp;
            g_bitmap_obj[i].vtop = (h < 0) ? 1 : 0;
            g_bitmap_obj[i].vstride = vstride;
            g_bitmap_obj[i].px = (uint8_t*)calloc((size_t)vstride * (size_t)abs_h, 1);
            if (!g_bitmap_obj[i].px) {
                g_bitmap_live[i] = 0;
                MW_TRACE("CreateDIBSection -> NULL (OOM %ux%u %ubpp)", (unsigned)w, (unsigned)abs_h, bpp);
                return NULL;
            }
            /* REAL pixel pointer in the GUEST's format/stride — ppvBits writes
             * are bytes the engine now reads back format-aware (mwb_get). */
            *ppvBits = g_bitmap_obj[i].px;
            MW_TRACE("CreateDIBSection(%dx%d %ubpp %s) -> 0x%08x bits=%p stride=%u",
                     w, h, bpp, (h < 0) ? "topdown" : "bottomup",
                     MW_HBITMAP_BASE | (unsigned)(i + 1), (void*)*ppvBits, vstride);
            return (void*)(uintptr_t)(MW_HBITMAP_BASE | (unsigned)(i + 1));
        }
    }
    MW_TRACE("CreateDIBSection -> NULL (table full)");
    return NULL;
}

/* ---- SWEEP-022 SW-936..940: DIB family — GetDIBits/SetDIBits real pixel
 * paths over the CreateDIBSection pool (3B/px BGR internal raster) ---- */
static MWBmp* mw_bmp_by_handle(void* hbmp) {
    uintptr_t v = (uintptr_t)hbmp;
    if ((v & 0xFFFF0000u) != MW_HBITMAP_BASE) return NULL;
    int i = (int)(v & 0xFFu) - 1;
    if (i < 0 || i >= MW_MEMDC_MAX || !g_bitmap_live[i]) return NULL;
    return &g_bitmap_obj[i];
}
/* ---- SWEEP-023 SW-981: DIB row format conversion (engine raster 24bpp BGR;
 * sources/dests may be 16bpp 5-5-5/5-6-5 or 32bpp BGRA with DWORD row stride) ---- */
static uint32_t mw_dib_stride(uint32_t w, uint16_t bpp) {
    return ((w * (uint32_t)bpp + 31u) / 32u) * 4u;
}
static void mw_dib_row_to_bgr24(const uint8_t* src, int w, uint16_t sbpp,
                                const uint32_t* masks, uint8_t* dst) {
    if (sbpp == 24) { memcpy(dst, src, (size_t)w * 3u); return; }
    if (sbpp == 32) {
        for (int x = 0; x < w; x++) {
            dst[x * 3 + 0] = src[x * 4 + 0]; /* B */
            dst[x * 3 + 1] = src[x * 4 + 1]; /* G */
            dst[x * 3 + 2] = src[x * 4 + 2]; /* R */
        }
        return;
    }
    if (sbpp == 16) {
        uint32_t rm = masks ? masks[0] : 0x7C00u, gm = masks ? masks[1] : 0x03E0u,
                 bm = masks ? masks[2] : 0x001Fu; /* BI_RGB 16bpp = 5-5-5 */
        int rs = 0, gs = 0, bs = 0; uint32_t r;
        for (r = rm, rs = 0; r && !(r & 1u); r >>= 1, rs++) {}
        for (r = gm, gs = 0; r && !(r & 1u); r >>= 1, gs++) {}
        for (r = bm, bs = 0; r && !(r & 1u); r >>= 1, bs++) {}
        for (int x = 0; x < w; x++) {
            uint16_t p = (uint16_t)(src[x * 2] | (src[x * 2 + 1] << 8));
            uint8_t rv = (uint8_t)(((p >> rs) & (rm >> rs)) * 255u /
                                   (rm >> rs ? (rm >> rs) : 1u));
            uint8_t gv = (uint8_t)(((p >> gs) & (gm >> gs)) * 255u /
                                   (gm >> gs ? (gm >> gs) : 1u));
            uint8_t bv = (uint8_t)(((p >> bs) & (bm >> bs)) * 255u /
                                   (bm >> bs ? (bm >> bs) : 1u));
            dst[x * 3 + 0] = bv; dst[x * 3 + 1] = gv; dst[x * 3 + 2] = rv;
        }
        return;
    }
    memset(dst, 0, (size_t)w * 3u); /* 1/4/8bpp palette sources: honest black */
}

/* ---- SW-1280 (SWEEP-059): stock 20-color system palette pulled up here —
 * the DIB color-table materializer below needs it for DIB_PAL_COLORS and
 * mw_SetDIBitsToDevice must decode palette DIBs BEFORE the palette family. ---- */
#define MW_PAL_BASE 0x00AB0000u
static const uint8_t g_stock_palette[20][3] = {
    {0,0,0},{128,0,0},{0,128,0},{128,128,0},{0,0,128},{128,0,128},{0,128,128},{192,192,192},
    {128,128,128},{255,0,0},{0,255,0},{255,255,0},{0,0,255},{255,0,255},{0,255,255},{255,255,255},
    {192,220,192},{166,202,240},{255,251,240},{160,160,164}
};
/* SW-1280 (SWEEP-059): materialize a DIB color table into BGRX quads.
 * winmine's six RT_BITMAP strips (tiles 16x256, LED digits 13x276, faces
 * 24x120) are 4bpp + 16-entry RGBQUAD tables blitted with SetDIBitsToDevice
 * using DIB_PAL_COLORS; the v1 converter memset those rows to "honest black"
 * so the whole board (bombs/digits/faces) painted black. Handles the
 * INFOHEADER 4-byte RGBQUAD table, the OS/2 COREHEADER 3-byte RGBTRIPLE
 * table, and DIB_PAL_COLORS 16-bit system-palette indices (stock 20). */
static void mw_dib_materialize_ctab(const uint8_t* h8, uint16_t bpp,
                                    uint32_t usage, uint8_t* out /*256*4*/) {
    memset(out, 0, 256 * 4);
    if (bpp > 8u) return;
    uint32_t n = 1u << bpp;
    uint32_t hdr = *(const uint32_t*)(const void*)h8;
    if (usage == 1u /*DIB_PAL_COLORS: WORD indices into the system palette*/) {
        const uint8_t* t = h8 + hdr;
        for (uint32_t i = 0; i < n; i++) {
            uint16_t pi = 0;
            memcpy(&pi, t + (size_t)i * 2u, 2u);
            const uint8_t* c = g_stock_palette[pi % 20u];
            out[i * 4 + 0] = c[0]; out[i * 4 + 1] = c[1]; out[i * 4 + 2] = c[2];
        }
        return;
    }
    if (hdr == 12u) { /* BITMAPCOREHEADER: RGBTRIPLE B,G,R */
        const uint8_t* t = h8 + 12;
        for (uint32_t i = 0; i < n; i++) {
            out[i * 4 + 0] = t[i * 3 + 0];
            out[i * 4 + 1] = t[i * 3 + 1];
            out[i * 4 + 2] = t[i * 3 + 2];
        }
        return;
    }
    uint32_t clr_used = *(const uint32_t*)(const void*)(h8 + 32);
    uint32_t phys = clr_used ? clr_used : n;
    if (phys > n) phys = n;
    const uint8_t* t = h8 + hdr;
    for (uint32_t i = 0; i < phys; i++) {
        out[i * 4 + 0] = t[i * 4 + 0];
        out[i * 4 + 1] = t[i * 4 + 1];
        out[i * 4 + 2] = t[i * 4 + 2];
    }
}
/* SW-1280 (SWEEP-059): palette-aware row decode for 1/4/8bpp DIBs; the
 * palette is the BGRX-quad table materialized by mw_dib_materialize_ctab. */
static void mw_dib_row_to_bgr24_pal(const uint8_t* src, int w, uint16_t sbpp,
                                    const uint8_t* pal, uint8_t* dst) {
    if (!pal) { mw_dib_row_to_bgr24(src, w, sbpp, NULL, dst); return; }
    if (sbpp == 8) {
        for (int x = 0; x < w; x++) {
            const uint8_t* e = pal + (size_t)src[x] * 4u;
            dst[x * 3 + 0] = e[0]; dst[x * 3 + 1] = e[1]; dst[x * 3 + 2] = e[2];
        }
        return;
    }
    if (sbpp == 4) {
        for (int x = 0; x < w; x++) {
            uint8_t v = (x & 1) ? (src[x >> 1] & 0x0Fu) : (uint8_t)(src[x >> 1] >> 4);
            const uint8_t* e = pal + (size_t)v * 4u;
            dst[x * 3 + 0] = e[0]; dst[x * 3 + 1] = e[1]; dst[x * 3 + 2] = e[2];
        }
        return;
    }
    if (sbpp == 1) {
        for (int x = 0; x < w; x++) {
            uint8_t v = (src[x >> 3] >> (7 - (x & 7))) & 1u;
            const uint8_t* e = pal + (size_t)v * 4u;
            dst[x * 3 + 0] = e[0]; dst[x * 3 + 1] = e[1]; dst[x * 3 + 2] = e[2];
        }
        return;
    }
    mw_dib_row_to_bgr24(src, w, sbpp, NULL, dst);
}
static void mw_dib_row_from_bgr24(const uint8_t* src, int w, uint16_t dbpp, uint8_t* dst, uint32_t stride) {
    memset(dst, 0, stride);
    if (dbpp == 24) { memcpy(dst, src, (size_t)w * 3u); return; }
    if (dbpp == 32) {
        for (int x = 0; x < w; x++) {
            dst[x * 4 + 0] = src[x * 3 + 0];
            dst[x * 4 + 1] = src[x * 3 + 1];
            dst[x * 4 + 2] = src[x * 3 + 2];
            dst[x * 4 + 3] = 0xFF;
        }
        return;
    }
    if (dbpp == 16) { /* emit 5-6-5 (the most common engine-adjacent format) */
        for (int x = 0; x < w; x++) {
            uint16_t p = (uint16_t)(((src[x * 3 + 2] >> 3) << 11) |
                                    ((src[x * 3 + 1] >> 2) << 5) |
                                    (src[x * 3 + 0] >> 3));
            dst[x * 2] = (uint8_t)(p & 0xFF); dst[x * 2 + 1] = (uint8_t)(p >> 8);
        }
        return;
    }
}
__attribute__((ms_abi)) int mw_GetDIBits(void* hdc, void* hbmp, uint32_t start,
        uint32_t lines, void* bits, void* pbmi, uint32_t usage) {
    (void)hdc; (void)start; (void)usage;
    MWBmp* b = mw_bmp_by_handle(hbmp);
    if (!b || !pbmi) return 0;
    uint8_t* h8 = (uint8_t*)pbmi;
    uint16_t want = *(const uint16_t*)(h8 + 14); /* caller presets biBitCount */
    if (want != 16 && want != 24 && want != 32) want = 24;
    *(uint32_t*)(h8 + 0) = 40;              /* biSize */
    *(int32_t*)(h8 + 4) = b->w;             /* biWidth */
    *(int32_t*)(h8 + 8) = b->vtop ? -b->h : b->h; /* SWEEP-028: honest sign */
    *(uint16_t*)(h8 + 12) = 1;              /* biPlanes */
    *(uint16_t*)(h8 + 14) = want;           /* SWEEP-023 SW-981: honored */
    *(uint32_t*)(h8 + 16) = 0;              /* BI_RGB */
    *(uint32_t*)(h8 + 20) = 0;              /* biSizeImage len 0 for BI_RGB ok */
    *(uint32_t*)(h8 + 24) = mw_dib_stride((uint32_t)b->w, want) * (uint32_t)b->h;
    if (!bits) return 1;                    /* header-only probe */
    uint32_t n = lines ? lines : (uint32_t)b->h;
    if (n > (uint32_t)b->h) n = (uint32_t)b->h;
    uint32_t stride = mw_dib_stride((uint32_t)b->w, want);
    uint8_t* row24 = (uint8_t*)malloc((size_t)b->w * 3u);
    if (!row24) return 0;
    if (b->vbpp == 0) {                     /* legacy 3B/px raster */
        for (uint32_t y = 0; y < n; y++) {  /* bottom-up row order */
            memcpy(row24, b->px + (size_t)y * (size_t)b->w * 3u, (size_t)b->w * 3u);
            mw_dib_row_from_bgr24(row24, b->w, want,
                                  (uint8_t*)bits + (size_t)(n - 1 - y) * stride, stride);
        }
    } else {                                /* SWEEP-028: view-format source */
        for (uint32_t y = 0; y < n; y++) {
            uint32_t dstY = b->vtop ? y : (n - 1 - y); /* top-down stays, bottom-up flips */
            for (int x = 0; x < b->w; x++) {
                uint32_t c = mwb_get(b, x, (int)y);
                row24[(size_t)x * 3 + 0] = (uint8_t)(c & 0xFF);
                row24[(size_t)x * 3 + 1] = (uint8_t)((c >> 8) & 0xFF);
                row24[(size_t)x * 3 + 2] = (uint8_t)((c >> 16) & 0xFF);
            }
            mw_dib_row_from_bgr24(row24, b->w, want,
                                  (uint8_t*)bits + (size_t)dstY * stride, stride);
        }
    }
    free(row24);
    MW_TRACE("GetDIBits(%dx%d -> %ubpp) %u rows", b->w, b->h, want, n);
    return (int)n;
}
__attribute__((ms_abi)) int mw_SetDIBits(void* hdc, void* hbmp, uint32_t start,
        uint32_t lines, const void* bits, const void* pbmi, uint32_t usage) {
    (void)hdc; (void)start; (void)usage;
    MWBmp* b = mw_bmp_by_handle(hbmp);
    if (!b || !bits || !pbmi) return 0;
    const uint8_t* h8 = (const uint8_t*)pbmi;
    int32_t w = *(const int32_t*)(h8 + 4);
    int32_t h = *(const int32_t*)(h8 + 8);
    uint16_t sbpp = *(const uint16_t*)(h8 + 14);
    uint32_t comp = *(const uint32_t*)(h8 + 16);
    if (w <= 0 || h == 0) return 0;
    const uint32_t* masks = (comp == 3 /*BI_BITFIELDS*/) ? (const uint32_t*)(h8 + 40) : NULL;
    uint32_t n = (uint32_t)(h > 0 ? h : -h);
    if (n > (uint32_t)b->h) n = (uint32_t)b->h;
    int32_t cw = w < b->w ? w : b->w;
    uint32_t stride = mw_dib_stride((uint32_t)w, sbpp);
    uint8_t* row24 = (uint8_t*)malloc((size_t)w * 3u);
    if (!row24) return 0;
    for (uint32_t y = 0; y < n; y++) {      /* source is bottom-up */
        const uint8_t* src = (const uint8_t*)bits + (size_t)y * stride;
        mw_dib_row_to_bgr24(src, cw, sbpp, masks, row24);
        uint32_t dstY = (h > 0) ? (n - 1 - y) : y; /* SWEEP-028: top-down source */
        uint8_t* dst = b->px + (b->vbpp ? (size_t)b->vstride * (size_t)dstY
                                        : (size_t)dstY * (size_t)b->w * 3u);
        if (b->vbpp == 32) {
            for (int x = 0; x < cw; x++) {
                dst[(size_t)x * 4 + 0] = row24[(size_t)x * 3 + 0];
                dst[(size_t)x * 4 + 1] = row24[(size_t)x * 3 + 1];
                dst[(size_t)x * 4 + 2] = row24[(size_t)x * 3 + 2];
                dst[(size_t)x * 4 + 3] = 0xFF;
            }
        } else {
            memcpy(dst, row24, (size_t)cw * 3u); /* legacy 3B/px raster */
        }
    }
    free(row24);
    MW_TRACE("SetDIBits(%dx%d %ubpp) -> %u rows", w, h, sbpp, n);
    return (int)n;
}
/* ---- SWEEP-023 SW-982/983: StretchDIBits + DIB color tables ---- */
__attribute__((ms_abi)) int mw_StretchDIBits(void* hdc, int dx, int dy, int dw, int dh,
        int sx, int sy, int sw, int sh, const void* bits, const void* pbmi,
        uint32_t usage, uint32_t rop) {
    (void)usage; (void)sx; (void)sy;
    MWBmp* D = mw_dc_surface(hdc);
    if (!D || !bits || !pbmi || dw <= 0 || dh <= 0 || sw <= 0 || sh <= 0) return 0;
    if ((rop & 0x00FFFFFFu) != 0x00CC0020u /*SRCCOPY*/) { mw_SetLastError(1); return 0; }
    const uint8_t* h8 = (const uint8_t*)pbmi;
    int32_t w = *(const int32_t*)(h8 + 4);
    int32_t h = *(const int32_t*)(h8 + 8);
    uint16_t sbpp = *(const uint16_t*)(h8 + 14);
    uint32_t comp = *(const uint32_t*)(h8 + 16);
    if (w <= 0 || h == 0) return 0;
    const uint32_t* masks = (comp == 3) ? (const uint32_t*)(h8 + 40) : NULL;
    /* SW-1280: palette table for 1/4/8bpp sources — replaces "honest black" */
    uint8_t mw_ctab2[256 * 4];
    const uint8_t* pal2 = NULL;
    if (sbpp <= 8u) { mw_dib_materialize_ctab(h8, sbpp, usage, mw_ctab2); pal2 = mw_ctab2; }
    uint32_t srch = (uint32_t)(h > 0 ? h : -h);
    uint32_t stride = mw_dib_stride((uint32_t)w, sbpp);
    uint8_t* row24 = (uint8_t*)malloc((size_t)w * 3u);
    if (!row24) return 0;
    int copied = 0;
    for (int row = 0; row < dh; row++) {
        int srcrow = (int)((long long)sh * row / dh); /* nearest-neighbor */
        /* SW-1280: flip within the caller's source-rect window [sy..sy+sh)
         * relative to the bits pointer (bottom-up), NOT off the full
         * biHeight — same contract fix as SetDIBitsToDevice. */
        uint32_t y = (h > 0) ? (uint32_t)(sh - 1 - srcrow)   /* bottom-up */
                             : (uint32_t)(sy + srcrow);      /* top-down */
        if (y >= srch) continue;
        if (pal2) mw_dib_row_to_bgr24_pal((const uint8_t*)bits + (size_t)y * stride, w,
                            sbpp, pal2, row24);
        else mw_dib_row_to_bgr24((const uint8_t*)bits + (size_t)y * stride, w,
                            sbpp, masks, row24);
        int ddy = dy + row;
        if (ddy < 0 || ddy >= D->h) continue;
        for (int col = 0; col < dw; col++) {
            int sxx = (int)((long long)sw * col / dw);
            if (sxx >= w) continue;
            int ddx = dx + col;
            if (ddx < 0 || ddx >= D->w) continue;
            mwb_set(D, ddx, ddy, /* SWEEP-028: view-format aware store */
                    (uint32_t)row24[(size_t)sxx * 3 + 0] |
                    ((uint32_t)row24[(size_t)sxx * 3 + 1] << 8) |
                    ((uint32_t)row24[(size_t)sxx * 3 + 2] << 16));
            copied++;
        }
    }
    free(row24);
    MW_TRACE("[GDI] StretchDIBits %dx%d@%d,%d <- %dx%d %ubpp (%d px)",
             dw, dh, dx, dy, sw, sh, sbpp, copied);
    return copied ? 1 : 0;
}
static uint32_t g_dib_ctab[MW_MEMDC_MAX][256];
static uint16_t g_dib_ctab_n[MW_MEMDC_MAX];
static int mw_dib_ctab_ix(void* hbmp) {
    uintptr_t v = (uintptr_t)hbmp;
    if ((v & 0xFFFF0000u) != MW_HBITMAP_BASE) return -1;
    int i = (int)(v & 0xFFu) - 1;
    return (i >= 0 && i < MW_MEMDC_MAX && g_bitmap_live[i]) ? i : -1;
}
__attribute__((ms_abi)) int mw_SetDIBColorTable(void* hdc, void* hbmp, uint32_t start,
        uint32_t count, const void* colors) {
    (void)hdc;
    int ix = mw_dib_ctab_ix(hbmp);
    if (ix < 0 || !colors || start >= 256 || count > 256u - start) return 0;
    memcpy(&g_dib_ctab[ix][start], colors, (size_t)count * 4u);
    if ((uint16_t)(start + count) > g_dib_ctab_n[ix])
        g_dib_ctab_n[ix] = (uint16_t)(start + count);
    MW_TRACE("SetDIBColorTable(%u..%u) stored", start, start + count);
    return (int)count;
}
__attribute__((ms_abi)) int mw_GetDIBColorTable(void* hdc, void* hbmp, uint32_t start,
        uint32_t count, void* colors) {
    (void)hdc;
    int ix = mw_dib_ctab_ix(hbmp);
    if (ix < 0 || !colors || start >= 256 || count > 256u - start) return 0;
    memcpy(colors, &g_dib_ctab[ix][start], (size_t)count * 4u);
    MW_TRACE("GetDIBColorTable(%u..%u) -> %u stored", start, start + count,
             (unsigned)g_dib_ctab_n[ix]);
    return (int)count;
}
/* MaskBlt: mask byte-map has no engine equivalent — honest contract:
 * plain SRCCOPY routes through BitBlt, everything else fails typed. */
__attribute__((ms_abi)) int mw_MaskBlt(void* hdcDst, int x, int y, int w, int h,
        void* hdcSrc, int xs, int ys, void* hbmMask, int xm, int ym, uint32_t rop) {
    (void)hbmMask; (void)xm; (void)ym;
    if ((rop & 0x00FFFFFFu) == 0x00CC0020u)
        return mw_BitBlt(hdcDst, x, y, w, h, hdcSrc, xs, ys, 0x00CC0020u);
    mw_SetLastError(1); /* ERROR_INVALID_FUNCTION */
    return 0;
}

