    const uint32_t* sub = (const uint32_t*)(b + 8);
    for (int i = 0; i < n && o < (int)sizeof(tmp) - 16; i++)
        o += snprintf(tmp + o, sizeof(tmp) - (size_t)o, "-%u", (unsigned)*(sub + i));
    char* s = (char*)mw_LocalAlloc(0x40, strlen(tmp) + 1);
    if (!s) return 0;
